import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"guides/plugins.md","filePath":"guides/plugins.md","lastUpdated":1781675678000}'),l={name:"guides/plugins.md"};function s(o,e,r,d,u,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p>Plugins are bot-scoped capability bundles installed from Supermarket. In v0.13, a plugin manifest can describe managed MCP resources, bundled skills, plugin hooks, configuration variables, authentication requirements, and optional install commands.</p><p>Memoh treats the configured Supermarket endpoint as the trusted source for plugin bundles. The default endpoint is <code>https://supermarket.memoh.ai</code>, and deployments can override it with the server <code>supermarket.base_url</code> config.</p><hr><h2 id="what-a-plugin-can-provide" tabindex="-1">What A Plugin Can Provide <a class="header-anchor" href="#what-a-plugin-can-provide" aria-label="Permalink to &quot;What A Plugin Can Provide&quot;">​</a></h2><p>A plugin manifest can include:</p><ul><li><strong>MCP resources</strong>: external tools or services that Memoh creates as plugin-managed MCP connections.</li><li><strong>Skills</strong>: reusable Markdown behavior modules, either referenced in the manifest or shipped inside the plugin bundle.</li><li><strong>Hooks</strong>: a <code>hooks.json</code> file that can run plugin-provided actions for supported hook events.</li><li><strong>Config variables</strong>: required or optional values collected during install, including secret values.</li><li><strong>Auth requirements</strong>: <code>managed_oauth</code>, <code>user_secret</code>, or no-auth MCP setup.</li><li><strong>Install commands</strong>: an <code>install</code> field that can be a string or a string array.</li></ul><p>Plugin-managed MCP resources are usually hidden implementation details of the plugin. Users manage the plugin as the product boundary instead of managing each generated MCP connection by hand.</p><hr><h2 id="trusted-plugin-bundles" tabindex="-1">Trusted Plugin Bundles <a class="header-anchor" href="#trusted-plugin-bundles" aria-label="Permalink to &quot;Trusted Plugin Bundles&quot;">​</a></h2><p>When you install a plugin from Supermarket, Memoh:</p><ol><li>Fetches the plugin manifest from Supermarket.</li><li>Downloads the plugin bundle from Supermarket when one exists.</li><li>Extracts only trusted bundle paths into the bot workspace plugin area: <ul><li><code>skills/</code></li><li><code>hooks.json</code></li><li><code>scripts/</code></li></ul></li><li>Runs manifest <code>install</code> commands from the plugin directory.</li><li>Creates the plugin installation record and plugin-managed MCP resources.</li></ol><p>The extracted plugin root is under <code>/data/.memoh/plugins/&lt;plugin_id&gt;</code> inside the bot workspace. Memoh clears that plugin root before extracting a newly installed bundle for the same plugin id.</p><p>Install commands run in the plugin root with these environment variables:</p><ul><li><code>MEMOH_PLUGIN_ID</code></li><li><code>MEMOH_PLUGIN_DIR</code></li><li><code>MEMOH_BOT_ID</code></li></ul><p>Only install trusted Supermarket plugins, because bundle files and install commands execute inside the target bot workspace.</p><hr><h2 id="bot-plugin-management" tabindex="-1">Bot Plugin Management <a class="header-anchor" href="#bot-plugin-management" aria-label="Permalink to &quot;Bot Plugin Management&quot;">​</a></h2><p>Open a bot&#39;s <strong>Detail Page</strong> and go to the <strong>Plugins</strong> tab to view installed plugins for that bot.</p><p>In v0.13, the Plugins tab shows:</p><ul><li>installed plugin name, description, icon, and homepage link</li><li>plugin status</li><li>whether the installation is enabled or disabled</li><li>an <strong>Authorize</strong> action when managed OAuth is required</li><li>an enable/disable switch for plugins that are ready or disabled</li><li>a shortcut back to Supermarket for installing more plugins</li></ul><p>The plugin API also supports bot-scoped list, get, enable, disable, uninstall, purge, managed OAuth authorize, and OAuth status refresh operations.</p><hr><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><p>Plugin installations use these status values:</p><ul><li><code>ready</code>: the plugin has the required configuration and auth; Memoh can enable its managed resources.</li><li><code>needs_config</code>: required manifest variables, environment variables, headers, or user-secret values are missing.</li><li><code>needs_auth</code>: the plugin requires managed OAuth and the bot has not completed authorization yet.</li><li><code>admin_required</code>: the plugin declares a managed OAuth <code>client_ref</code>, but the server does not have a usable OAuth client configured for that reference.</li><li><code>disabled</code>: the plugin was turned off; plugin-managed MCP connections are inactive.</li><li><code>uninstalled</code>: the plugin was uninstalled from the bot; managed MCP connections and plugin resource rows were removed.</li></ul><p>Purging an installation deletes the installation record and saved config. Extracted bundle files are no longer discovered when the installation is not enabled, and a later reinstall rewrites the plugin root.</p><hr><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Plugins can use two main auth models:</p><ul><li><strong>Managed OAuth</strong>: the manifest declares <code>auth_requirements[].type = &quot;managed_oauth&quot;</code>. If it uses <code>client_ref</code>, an operator must configure that OAuth client on the Memoh server. Users then authorize the plugin from Supermarket install or from the bot&#39;s Plugins tab.</li><li><strong>User secret</strong>: the manifest declares required variables, environment entries, or headers. Users provide the values during install. Missing required values put the plugin in <code>needs_config</code>.</li></ul><p>When managed OAuth succeeds, Memoh refreshes the plugin status and enables the managed MCP resources once the plugin is <code>ready</code>.</p><hr><h2 id="how-plugins-relate-to-other-features" tabindex="-1">How Plugins Relate To Other Features <a class="header-anchor" href="#how-plugins-relate-to-other-features" aria-label="Permalink to &quot;How Plugins Relate To Other Features&quot;">​</a></h2><ul><li><strong>Supermarket</strong> is where plugins and standalone skills are discovered and installed.</li><li><strong>Skills</strong> can come from a standalone Supermarket skill or from an enabled plugin bundle.</li><li><strong>MCP</strong> resources can be created and managed by plugins; plugin-managed MCP resources may be hidden from normal MCP management.</li><li><strong>Hooks</strong> can be provided by enabled, ready plugin bundles through <code>hooks.json</code>.</li></ul><hr><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="/guides/supermarket.html">Supermarket</a></li><li><a href="/guides/skills.html">Skills</a></li><li><a href="/guides/mcp.html">MCP</a></li><li><a href="/guides/bot.html">Bot Management</a></li></ul>',38)])])}const p=a(l,[["render",s]]);export{g as __pageData,p as default};
